let input=3;
/** @template T
 * @param {T} n
 * @returns {T} */
function helper(n){return n;}const result=helper(input);export const observed=result+1;

let input={n:3};
/** @template T
 * @param {T} n
 * @returns {T} */
function helper(n){return n;}const result=helper(input);export const observed=result.n;

/** @template T
 * @param {T} n
 * @returns {T} */
function helper(n){return n;}const result=helper(3);export const observed=result+1;

/** @type {string|null} */ let value="owned";
/** @template T
 * @param {T} n
 * @param {null} later
 * @returns {T} */
function helper(n,later){void later;return n;}const result=helper(value,(value=null));export const observed=result.length;

/** @template T
 * @param {T} n
 * @returns {T} */
function helper(n){return n;}export async function outer(){const result=helper(await Promise.resolve(3));return result+1;}export const observed=outer();

/** @template T
 * @param {T} n
 * @returns {T} */
function helper(n){return n;}
/** @returns {Generator<number,number,number>} */
export function* outer(){const result=helper(yield 3);return result+1;}const iterator=outer();export const observed=[iterator.next(),iterator.next(4)];

/** @typedef {{n:number}} Row */
function helper(){return 3;}
/** @type {Row} */ const other={n:4};const result=helper();export const observed=result+other.n;

/** @typedef {{n:number}} Row */
/** @returns {Row} */
function helper(){return {n:3};}
/** @type {Row} */ const other={n:4};const result=helper();export const observed=result.n+other.n;

/** @typedef {{n:number,left?:number}} Row */
const outside={n:3};
/** @returns {Row} */
function helper(){return outside;}export function outer(){/** @typedef {{n:number,right?:number}} Row */ const marker=0;void marker;/** @type {Row} */ const local={n:4};void local;const result=helper();return typeof result;}export const observed=outer();
